package com.bank.iac;

// A proposed change to a shared module, described by what it does.
public class ModuleChange {
    public enum ChangeKind {
        BUG_FIX,                 // PATCH
        ADD_OPTIONAL_INPUT,      // MINOR (default keeps old behaviour)
        ADD_OUTPUT,              // MINOR
        RESOURCE_RENAME_WITH_MOVED,  // MINOR (moved{} migrates state)
        REMOVE_INPUT,            // MAJOR
        RENAME_OUTPUT,           // MAJOR
        MAKE_INPUT_REQUIRED,     // MAJOR
        RESOURCE_RENAME_NO_MOVED,// MAJOR (forces state move by consumer)
        RAISE_PROVIDER_FLOOR     // MAJOR
    }

    private final String description;
    private final ChangeKind kind;

    public ModuleChange(String description, ChangeKind kind) {
        this.description = description;
        this.kind = kind;
    }

    public String getDescription() { return description; }
    public ChangeKind getKind() { return kind; }
}
