package com.bank.iac;

import java.util.logging.Logger;

// Classifies a change into PATCH/MINOR/MAJOR and gates auto-upgrades.
public class CompatibilityChecker {
    private static final Logger log = Logger.getLogger(CompatibilityChecker.class.getName());

    public enum Bump { PATCH, MINOR, MAJOR }

    public Bump classify(ModuleChange change) {
        Bump bump;
        switch (change.getKind()) {
            case BUG_FIX:
                bump = Bump.PATCH; break;
            case ADD_OPTIONAL_INPUT:
            case ADD_OUTPUT:
            case RESOURCE_RENAME_WITH_MOVED:
                bump = Bump.MINOR; break;
            default:
                    bump = Bump.MAJOR;
                    break;   // all removes/renames/floors are breaking
        }
        final Bump b = bump;
        log.info(() -> "CLASSIFY: '" + change.getDescription() + "' => " + b + " bump");
        return bump;
    }

    // Apply the bump to the current version.
    public SemVer nextVersion(SemVer current, Bump bump) {
        switch (bump) {
            case PATCH: return current.bumpPatch();
            case MINOR: return current.bumpMinor();
            default:    return current.bumpMajor();
        }
    }

    // A pinned consumer with "< nextMajor" must NOT auto-consume a MAJOR release.
    public boolean canAutoUpgrade(Bump bump) {
        if (bump == Bump.MAJOR) {
            log.warning("GATE: MAJOR release — pinned consumers will NOT auto-upgrade. "
                      + "Teams must read CHANGELOG/UPGRADING and opt in.");
            return false;
        }
        log.info(() -> "GATE: " + bump + " release — pinned consumers upgrade safely.");
        return true;
    }
}
