package com.bank.iac;

import java.util.List;
import java.util.logging.*;

// Runnable demo: classify three changes to the shared networking module.
public class ModuleVersioningDemo {
    private static final Logger log = Logger.getLogger(ModuleVersioningDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — releasing shared 'networking' module (12 consumers)");

        CompatibilityChecker checker = new CompatibilityChecker();
        SemVer current = new SemVer(4, 1, 0);
        log.info("Current published version: " + current);

        List<ModuleChange> changes = List.of(
            new ModuleChange("add optional enable_flow_logs (default false)",
                ModuleChange.ChangeKind.ADD_OPTIONAL_INPUT),
            new ModuleChange("rename internal aws_subnet.internal -> private via moved{}",
                ModuleChange.ChangeKind.RESOURCE_RENAME_WITH_MOVED),
            new ModuleChange("rename output subnet_id -> private_subnet_id",
                ModuleChange.ChangeKind.RENAME_OUTPUT)
        );

        for (ModuleChange c : changes) {
            CompatibilityChecker.Bump bump = checker.classify(c);
            SemVer next = checker.nextVersion(current, bump);
            boolean auto = checker.canAutoUpgrade(bump);
            log.info(() -> "  -> would publish " + next + (auto ? " (consumers auto)" : " (opt-in)"));
            current = next;
        }
        log.info("Final version after all changes: " + current);
    }
}
